// @generated by:gauntlet run:anatoly-orion-recon
mod common;

use anatoly::{
    scan::{Scanner, scan_configured},
    scan_options::ScanOptions,
};
use common::{Server, limits, response};
use serde_json::Value;

fn options() -> ScanOptions {
    let mut options = ScanOptions {
        samples: 1,
        paths: vec![],
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    options
}

fn scan(server: &Server, options: &ScanOptions, requests: usize) -> Value {
    let mut budget = limits();
    budget.max_requests = requests;
    budget.max_body = 32_768;
    serde_json::to_value(scan_configured(&server.url, budget, options).unwrap()).unwrap()
}

fn technology<'a>(report: &'a Value, name: &str) -> &'a Value {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["name"] == name)
        .unwrap_or_else(|| panic!("missing {name}: {report}"))
}

fn assert_unknown_version(report: &Value) {
    assert!(report["version"].is_null());
    assert!(report["version_candidates"].as_array().unwrap().is_empty());
    assert_eq!(report["verdict"], "inconclusive");
}

#[test]
fn t_ac_12_same_origin_asset_paths_identify_applications_without_guessing_their_versions() {
    for (markup, name) in [
        (
            "<script src='/wp-content/plugins/example.js?ver=8.4.26'></script>",
            "WordPress",
        ),
        (
            "<link href='/wp-includes/css/example.css?ver=8.4.26'>",
            "WordPress",
        ),
        (
            "<img src='/sites/default/files/logo.png?ver=8.4.26'>",
            "Drupal",
        ),
        (
            "<script src='/core/misc/drupal.js?ver=8.4.26'></script>",
            "Drupal",
        ),
        (
            "<script src='/media/system/js/core.js?ver=8.4.26'></script>",
            "Joomla",
        ),
        (
            "<link href='/cpresources/synthetic/style.css?ver=8.4.26'>",
            "Craft CMS",
        ),
    ] {
        let server = Server::new(move |_| response("200 OK", "", markup));
        let mut settings = options();
        settings.discover = false;

        let report = scan(&server, &settings, 4);

        let found = technology(&report, name);
        assert!(found["versions"].as_array().unwrap().is_empty());
        assert_eq!(report["runtime"]["status"], "inferred");
        assert_unknown_version(&report);
        assert_eq!(server.paths.lock().unwrap().as_slice(), ["/"]);
    }
}

