#[test]
fn t_ac_12_attribution_names_must_follow_powered_by_without_inert_or_unrelated_text() {
    for body in [
        "<p>Powered by <script>CraftCMS</script></p>",
        "<p>Powered by StaticHub. Learn about Craft CMS</p>",
    ] {
        let server = Server::new(move |_| response("200 OK", "", body));
        let mut settings = options();
        settings.discover = false;

        let report = scan(&server, &settings, 4);

        assert!(
            !report["technologies"]
                .as_array()
                .unwrap()
                .iter()
                .any(|t| t["name"] == "Craft CMS"),
            "{body}: {report}"
        );
        assert_unknown_version(&report);
    }
}

#[test]
fn t_ac_12_composer_requirements_identify_products_without_promoting_constraints_to_versions() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "Content-Type: application/json\r\n",
            r#"{
        "require":{"craftcms/cms":"^5.8","yiisoft/yii2":"~2.0.53","php":"8.4.26"},
        "require-dev":{"laravel/framework":"^12.0"}}
    "#,
        )
    });
    let mut settings = options();
    settings.discover = false;

    let report = serde_json::to_value(
        scan_configured(&format!("{}composer.json", server.url), limits(), &settings).unwrap(),
    )
    .unwrap();

    for name in ["Craft CMS", "Yii"] {
        assert!(
            technology(&report, name)["versions"]
                .as_array()
                .unwrap()
                .is_empty()
        );
    }
    assert!(
        !report["technologies"]
            .as_array()
            .unwrap()
            .iter()
            .any(|t| t["name"] == "Laravel")
    );
    assert_unknown_version(&report);
}

#[test]
fn t_ac_12_composer_lock_keeps_package_versions_and_ignores_development_packages() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "Content-Type: application/json\r\n",
            r#"{
        "packages":[{"name":"craftcms/cms","version":"v5.8.1"},{"name":"yiisoft/yii2","version":"2.0.53"}],
        "packages-dev":[{"name":"laravel/framework","version":"12.0.0"}],
        "platform":{"php":"8.4.26"}}
    "#,
        )
    });
    let mut settings = options();
    settings.discover = false;

    let report = serde_json::to_value(
        scan_configured(&format!("{}composer.lock", server.url), limits(), &settings).unwrap(),
    )
    .unwrap();

    assert!(
        technology(&report, "Craft CMS")["versions"]
            .as_array()
            .unwrap()
            .contains(&Value::from("5.8.1"))
    );
    assert!(
        technology(&report, "Yii")["versions"]
            .as_array()
            .unwrap()
            .contains(&Value::from("2.0.53"))
    );
    assert!(
        !report["technologies"]
            .as_array()
            .unwrap()
            .iter()
            .any(|t| t["name"] == "Laravel")
    );
    assert_unknown_version(&report);
}

