#[test]
fn t_ac_12_reusing_a_scanner_keeps_target_budgets_and_observations_isolated() {
    let first = Server::new(|_| {
        response(
            "200 OK",
            "X-Powered-By: PHP/8.4.26\r\nX-Generator: Craft CMS\r\n",
            "application",
        )
    });
    let second = Server::new(|_| response("200 OK", "", "different application"));
    let engine = Scanner::new().unwrap();
    let mut settings = options();
    settings.discover = false;
    let mut budget = limits();
    budget.max_requests = 1;

    let observed = engine.scan(&first.url, budget.clone(), &settings).unwrap();
    let neutral =
        serde_json::to_value(engine.scan(&second.url, budget, &settings).unwrap()).unwrap();

    assert_eq!(observed.requests_sent, 1);
    assert_eq!(neutral["requests_sent"], 1);
    assert!(neutral["technologies"].as_array().unwrap().is_empty());
    assert_eq!(neutral["runtime"]["status"], "unknown");
    assert_unknown_version(&neutral);
    assert!(!neutral.to_string().contains(&first.url));
}

#[test]
fn t_ac_12_application_version_caps_preserve_only_versions_with_retained_provenance() {
    for count in [65, 100] {
        let packages: Vec<_> = (0..count)
            .map(
                |index| serde_json::json!({"name":"craftcms/cms","version":format!("5.8.{index}")}),
            )
            .collect();
        let body = serde_json::json!({"packages":packages}).to_string();
        let server = Server::new(move |_| response("200 OK", "", &body));
        let mut settings = options();
        settings.discover = false;
        let mut budget = limits();
        budget.max_body = 32_768;

        let report = serde_json::to_value(
            scan_configured(&format!("{}composer.lock", server.url), budget, &settings).unwrap(),
        )
        .unwrap();

        let craft = technology(&report, "Craft CMS");
        let versions = craft["versions"].as_array().unwrap();
        let observations = craft["observations"].as_array().unwrap();
        assert_eq!(versions.len(), 64);
        assert_eq!(observations.len(), 64);
        assert!(
            versions
                .iter()
                .all(|version| observations.iter().any(|o| o["version"] == *version))
        );
        assert!(
            observations
                .iter()
                .all(|o| versions.contains(&o["version"]))
        );
        assert_eq!(craft["truncated"], true);
        assert_eq!(report["analysis"]["coverage_complete"], false);
        assert!(!report["analysis"]["gaps"].as_array().unwrap().is_empty());
        assert_unknown_version(&report);
    }
}

#[test]
fn t_ac_12_conflicting_application_versions_retain_their_original_channel_and_source() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "X-Powered-By: Craft CMS 4.9.0\r\n",
            "<meta name='generator' content='Craft CMS 5.8.1'>",
        )
    });
    let mut settings = options();
    settings.discover = false;

    let report = scan(&server, &settings, 4);

    let observations = technology(&report, "Craft CMS")["observations"]
        .as_array()
        .unwrap();
    assert_eq!(observations.len(), 2);
    for (method, version, source_label) in [
        ("header", "4.9.0", "[x-powered-by]"),
        ("generator", "5.8.1", "[generator]"),
    ] {
        let observation = observations.iter().find(|o| o["method"] == method).unwrap();
        assert_eq!(observation["version"], version);
        assert!(
            observation["source"]
                .as_str()
                .unwrap()
                .contains(source_label)
        );
        assert!(
            observation["source"]
                .as_str()
                .unwrap()
                .starts_with(&server.url)
        );
    }
    assert_unknown_version(&report);
}

#[test]
fn t_ac_11_many_excluded_links_cannot_hide_a_later_permitted_diagnostic() {
    let mut body: String = (0..129)
        .map(|i| format!("<a href='/private/{i}/info.php'>excluded</a>"))
        .collect();
    body.push_str("<a href='/public/phpinfo.php'>allowed</a>");
    let server = Server::new(move |path| {
        if path == "/" {
            response("200 OK", "", &body)
        } else {
            response("200 OK", "", r#"{"php_version":"8.4.26"}"#)
        }
    });
    let mut settings = options();
    settings.max_linked_paths = 1;
    settings.network.exclude_paths.push("/private/".into());

    let report = scan(&server, &settings, 4);

    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/public/phpinfo.php"]
    );
    assert_eq!(report["analysis"]["discovery_limited"], false);
    assert_eq!(report["version_status"], "affected_range");
}
